contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        uint256 contractBefore = address(c).balance;
        uint256 testBefore = address(this).balance;

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;
        uint256 contractAfterDeposit = address(c).balance;
        uint256 testAfterDeposit = address(this).balance;

        c.withdraw(amount); if (__ESBMC_reverted()) return;
        uint256 contractAfterWithdraw = address(c).balance;
        uint256 testAfterWithdraw = address(this).balance;

        assert(
            testAfterDeposit == testBefore - amount &&
            contractAfterDeposit == contractBefore + amount &&
            testAfterWithdraw == testAfterDeposit + amount &&
            contractAfterWithdraw == contractBefore &&
            testAfterWithdraw == testBefore
        );
    }

    receive() external payable {}
}

