// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        uint256 contractBefore = address(c).balance;
        uint256 testBefore = address(this).balance;
        try c.deposit{value: amount}() {} catch { return; }
        uint256 contractAfterDeposit = address(c).balance;
        uint256 testAfterDeposit = address(this).balance;
        try c.withdraw(amount) {} catch { return; }
        uint256 contractAfterWithdraw = address(c).balance;
        uint256 testAfterWithdraw = address(this).balance;
        assertTrue(testAfterDeposit == testBefore - amount &&
            contractAfterDeposit == contractBefore + amount &&
            testAfterWithdraw == testAfterDeposit + amount &&
            contractAfterWithdraw == contractBefore &&
            testAfterWithdraw == testBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
